// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function settingsPage(){ctx.shell(`${ctx.head('Configurações','Personalize os dados da empresa, a aparência e suas propostas.')}<form id="settings-form"><section class="panel"><div class="panelhead"><h2>Empresa e identidade visual</h2></div><div class="panelbody grid2">${ctx.field('Nome da empresa','company','text',ctx.settings.company||'Avelon Têxtil','required maxlength="200"')}${ctx.field('Contatos para o orçamento','contact','text',ctx.settings.contact||'','maxlength="500"')}<label class="field">Logo da empresa (PNG / JPG, até 350 KB)<input type="file" id="logo-file" accept="image/png,image/jpeg"></label>${ctx.field('Cor de destaque','accent','color',ctx.settings.accent||'#ddab63')}<p class="muted span2" style="font-size:12px">A logo original Avelon é usada enquanto nenhuma imagem personalizada for enviada.</p></div></section><section class="panel"><div class="panelhead"><h2>Padrões de orçamento</h2></div><div class="panelbody grid2"><label class="field">Método padrão<select name="method"><option value="markup" ${ctx.settings.method!=='margin'?'selected':''}>Acréscimo sobre o custo</option><option value="margin" ${ctx.settings.method==='margin'?'selected':''}>Margem sobre a venda</option></select></label>${ctx.field('Percentual padrão (%)','percentage','number',ctx.settings.percentage??30,'required min="0" max="9999" step="0.01"')}${ctx.field('Validade padrão (dias)','valid_days','number',ctx.settings.valid_days||7,'required min="1" max="365" step="1"')}<label class="field span2">Condições de pagamento, entrada e prazo de produção<textarea name="conditions" maxlength="10000" placeholder="Ex.: entrada de 50%; produção em até 15 dias após aprovação da arte.">${ctx.esc(ctx.settings.conditions||'')}</textarea></label><p class="note span2">Esses padrões preenchem novos orçamentos. Propostas já salvas preservam seus preços, contatos, logo e condições da emissão. Você pode ajustar o percentual e as condições em cada nova proposta.</p></div></section><section class="panel"><div class="panelbody"><h2 style="font:700 17px Manrope">Telas e módulos</h2><p class="muted">Disponíveis nesta versão: visão geral, clientes, produtos e orçamentos. A ordem do menu é fixa. Editor de telas, reordenação de módulos, módulos financeiros serão etapas futuras.</p></div></section><p id="settings-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="change-password">Alterar minha senha</button><button class="primary" type="submit">Salvar configurações</button></div></form>`);ctx.$('#change-password').onclick=ctx.passwordDialog;document.querySelectorAll('#settings-form [name],#logo-file').forEach(el=>{const area=el.name==='accent'?'settings_appearance':['company','contact'].includes(el.name)||el.id==='logo-file'?'settings_company':'settings_quotes';if(!ctx.can(area,'view'))el.closest('label').hidden=true;else if(!ctx.can(area,'edit'))el.disabled=true;});ctx.$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const submitted=Object.fromEntries(new FormData(e.target));const data={...ctx.settings};for(const [k,v] of Object.entries(submitted)){const area=k==='accent'?'settings_appearance':['company','contact'].includes(k)?'settings_company':'settings_quotes';if(ctx.can(area,'edit'))data[k]=v;}for(const k of ['percentage','valid_days'])if(data[k]!==undefined)data[k]=Number(data[k]);if(data.method==='margin'&&data.percentage>=100)throw Error('A margem deve ser menor que 100%.');if(ctx.can('settings_company','edit'))data.logo=ctx.settings.logo||'';const file=ctx.can('settings_company','edit')?ctx.$('#logo-file').files[0]:null;if(file){if(!['image/png','image/jpeg'].includes(file.type)||file.size>350000)throw Error('Envie uma imagem PNG ou JPG de até 350 KB.');data.logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}await ctx.api('/rest/v1/rpc/save_settings',{method:'POST',body:{p_data:data}});await ctx.load();ctx.render('settings');ctx.toast('Configurações salvas.')}catch(err){ctx.$('#settings-error').className='error';ctx.$('#settings-error').textContent=err.message;b.disabled=false}}}
Object.assign(ctx,{settingsPage});
}
